// Fibonacci sequence

var num = 12;
var thr = 6; //関数の繰り返し回数に関するしきい値
var fibo = [];
var SGN = [1, 1, -1, -1];
var mySize;
var colorNum;
var color1, color2, color3 ,grad;
let colors1 = "e3d7a3BF-f5989d33-ea618e40-fce4d6b3-caac7133".split("-").map((a) => "#" + a);
let colors2 = "6cbbd4BF-5863b140-5282a1BF-fee8f733-c1f29b80".split("-").map((a) => "#" + a);
let colors3 = "1b1b1bBF-29292940-f3f3f3BF-222222b3-ff000080".split("-").map((a) => "#" + a);
let colors4 = "70c1b3BF-aaf0d340-50514f33-ffe066b3-247ba080".split("-").map((a) => "#" + a);
let colors5 = "3c164233-38637540-08637533-b2ff9eb3-1dd3b080".split("-").map((a) => "#" + a);
let colorbg = "2c363f".split("-").map((a) => "#" + a);

function setup() {
	pixelDensity(5);
	mySize = max(windowWidth, windowHeight);
	translate(windowWidth/2, windowHeight/2);
  createCanvas(mySize,mySize);
  background(colorbg);	
	colorNum = random([colors1, colors2, colors3, colors4, colors5]);
  generateFibo(num); //num項目までのフィボナッチ数列を生成
  divSquare(0, 0, 2, 1, 4, 8);//正方形のフィボナッチ分割
}

function colRect(xPos, yPos, wd, ht, ind) {
  var scalar = width / fibo[0];
  // fill(random(colors1));
	noFill();
	strokeCap(SQUARE);
	stroke(random(colorNum));
	color1 = random(colorNum);
	color2 = random(colorNum);
	color3 = random(colorNum);
	grad = drawingContext.createLinearGradient(scalar * xPos - scalar * wd, scalar * yPos - 2*scalar * ht, scalar * xPos - scalar * wd, scalar * yPos + 2*scalar * ht);
	grad.addColorStop(0, color1);
	grad.addColorStop(0.5, color2);
	grad.addColorStop(1, color3);
	drawingContext.strokeStyle = grad;
	strokeWeight(random(50));
  line(scalar * (xPos-wd), scalar * (yPos-ht),scalar * (xPos-wd), scalar * (yPos+ht));
  line(scalar * (xPos+wd), scalar * (yPos-ht),scalar * (xPos+wd), scalar * (yPos+ht));
	strokeWeight(random(30));
	line(scalar * (xPos-wd), scalar * (yPos-ht),scalar * (xPos+wd), scalar * (yPos-ht));
  line(scalar * (xPos+wd), scalar * (yPos+ht),scalar * (xPos-wd), scalar * (yPos+ht));
	strokeWeight(random(20));
	point(scalar * (xPos-wd), scalar * (yPos-ht));
	point(scalar * (xPos+wd), scalar * (yPos+ht));
}

function divRect(xPos, yPos, ind, itr, sgnX, sgnY){
  for(var i  = 0; i < num-ind; i++){
    var lng = fibo[i+ind];
    var newSgnX = sgnX * SGN[(i+1) % 4];
    var newSgnY = sgnY * SGN[i % 4];
    colRect(xPos, yPos, newSgnX * lng, newSgnY * lng, ind + i);
    xPos += newSgnX * lng;
    yPos += newSgnY * lng;
    if (itr < thr){
      divSquare(xPos, yPos, ind + i, itr + 1, -newSgnX, -newSgnY);
    }
  }
}

//正方形の位置(xPos, yPos)，フィボナッチ数列の項数ind，
//関数の繰り返し回数itr，正方形の描画に関する符号(sgnX,sgnY)を引数とする分割
function divSquare(xPos, yPos, ind, itr, sgnX, sgnY){
  //(num-ind)項目のフィボナッチ数(=fibo[ind])を一辺とする正方形を順に分割
  for(var i = 0; i < num - ind; i++){
    //フィボナッチ数列の順序を逆にしているため，iが大きいほどフィボナッチ長方形は小さい
    var lng0 = fibo[i + ind + 1]; //フィボナッチ長方形の横幅(短辺)
    var lng1 = fibo[i + ind];  //フィボナッチ長方形の縦幅(長辺)
    var newSgnX = sgnX * SGN[i % 4];  //長方形を描画する方向
    var newSgnY = sgnY * SGN[(i + 1) % 4];
    colRect(xPos, yPos, //フィボナッチ長方形の位置
      newSgnX * lng0, newSgnY * lng1, //フィボナッチ長方形の大きさ
      ind + i + 1); //項数に対応して長方形の色を決定
    xPos += newSgnX * lng0;
    yPos += newSgnY * lng1;
    if (itr < thr){ //関数の繰り返し回数がしきい値未満ならば長方形をフィボナッチ分割
      divRect(xPos, yPos,
        i + ind + 1, //フィボナッチ長方形の短辺の項数を渡す
        itr + 1, //繰り返し回数を1増やして渡す
        -newSgnX, -newSgnY);  //敷き詰めの回り込みの向きを逆にする
    }
  }
}

function generateFibo(ind){
  fibo = [0, 1];
  for(var i = 1; i < ind; i++){
    fibo = append(fibo, fibo[i-1] + fibo[i]);
  }
  fibo = reverse(fibo); //配列の番号付けを逆にする
}

function mouseClicked(){
  num = int(random(8, 16));
  thr = int(random(4, 8));
  background(colorbg);
	colorNum = random([colors1, colors2, colors3, colors4, colors5]);
  generateFibo(num);
  divSquare(0, 0, 0, 0, int(random(4,8)), int(random(2,8)));
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("Fibonacci sequence_Lines", "png");
	}
}

